import {BaseLineMap} from '../types/base-line-map';
import {CreateDocRawResponse} from '../types/create-doc-raw-response';
import {DocRaw} from '../types/doc-raw';
import {DOC_TYPE} from 'shared';

/**
 * creates and returns DocRaw. See interface CreateDocRawResponse for documentation.
 * This function was generated by claude. Comments added by me.
 * @param lines
 */
export function createDocRawArr(lines: BaseLineMap[]): CreateDocRawResponse {
    const docs: DocRaw[] = [];
    // elements that have no HEAD. Is used for lines before the first head.
    const noHead: DocRaw[] = [];
    // currently used HEAD. One HEAD is a doc. ALCs and TEXTs before next POS are assigned to the head.
    let currentHead: DocRaw | undefined;
    // currently used POS. POS is assigned to HEAD. ALCs and TEXTs after POS but before next HEAD are assigned to that POS
    let currentPos: DocRaw | undefined;

    for (const line of lines) {
        const node: DocRaw = {...line};

        // new document starts. Reset currentPos and set current head.
        if (line.type === DOC_TYPE.HEAD) {
            // HEAD collects POSs, TEXTs and ALCs. Initialize empty array.
            node.pos = [];
            node.texts = [];
            node.alcs = [];
            // for convenience and checks later unknown lines are only added to head.
            node.unknownLines = [];
            currentHead = node;
            currentPos = undefined;
            docs.push(node);
            continue;
        }

        // no current head exists. This means the element has no head.
        if (currentHead === undefined) {
            noHead.push(node);
            continue;
        }

        // add current pos to head and set current pos.
        if (line.type === DOC_TYPE.POS) {
            currentHead.pos?.push(node);
            // POS collects TEXTs and ALCs. Initialize empty array.
            node.texts = [];
            node.alcs = [];
            currentPos = node;
            continue;
        }

        // line is either TEXT or ALC.
        if (line.type === DOC_TYPE.TEXT || line.type === DOC_TYPE.ALC) {
            // if no currentPos is set the TEXT or ALC belongs to currentHead.
            const owner = currentPos ?? currentHead;
            const keyToAddTo = line.type === DOC_TYPE.TEXT ? 'texts' : 'alcs';
            const listRef = owner[keyToAddTo];
            if (!listRef) {
                throw new Error(`createDocRawArr: ${keyToAddTo} wurde nicht initialisiert für ${owner.type}.`);
            }
            listRef.push(node);
            continue;
        }

        // unknown type. Add to unknown lines.
        currentHead.unknownLines?.push(node);
    }

    return {docs, noHead};
}